mapper.select:
select s.id
from sys_video_inspection_route_rel s
where
s.inspection_route_id = #{param.inspectionRouteId}
and s.delete_flag = 0
and s.tenant_id = #{param.tenantId}
and s.industry_code = #{param.industryCode}

select count(*)
from `sys_video_inspection_route` s
where s.inspection_route_name = #{param.inspectionRouteName}
and s.tenant_id = #{param.tenantId}
and s.industry_code = #{param.industryCode}
and s.delete_flag = 0

    and s.id != #{param.inspectionRouteId}

mapper.update:
update `sys_video_inspection_route`
set route_status = #{param.routeStatus}, modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.id}

    and route_status = #{param.originalRouteStatus}

mapper.select:
select id inspectionRouteSubId, inspection_route_id, device_code, channel_code, preset_id, route_status,
duration_time, duration_unit, sort_seq, tenant_id, industry_code, app_ver_code
from sys_video_inspection_route_rel where id = #{id}

select rel.id inspectionRouteSubId
from sys_video_inspection_route_rel rel
inner join vm_order_devices o on rel.tenant_id = o.tenant_id and rel.industry_code = o.industry_code and rel.device_code = o.device_code
where rel.id = #{param.inspectionRouteSubId}
${param.dataScope}
limit 1

select rel.device_code, rel.channel_code, rel.preset_id, r.`pause_cruise_flag`
from sys_video_inspection_route_rel rel inner join sys_video_inspection_route r on r.id = rel.inspection_route_id
where rel.id = #{id}

mapper.update:
update sys_video_inspection_route_rel
set route_status = #{param.routeStatus},

    inspection_start_time = #{param.inspectionStartTime},


    pause_start_time = #{param.pauseStartTime},

modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.id} and route_status = #{param.originalRouteStatus}

update `sys_video_inspection_route`
set route_status = 0, modifier = #{param.modifier}, update_time = #{param.updateTime}
where id = #{param.inspectionRouteId}

mapper.select:
select id inspectionRouteId,
       inspection_route_name inspectionRouteName,
       route_status routeStatus
from `sys_video_inspection_route`
    where id = #{param.inspectionRouteId}
        and tenant_id = #{param.tenantId}
        and industry_code = #{param.industryCode}
        and delete_flag = 0

mapper.update:
update `sys_video_inspection_route`
set delete_flag = '1'
where id = #{param.inspectionRouteId}
and tenant_id = #{param.tenantId} and industry_code = #{param.industryCode}

update.foreach:
update `sys_video_inspection_route_rel`
device_code = #{item.deviceCode}, channel_code = #{item.channelCode}, preset_id = #{item.presetId}, sort_seq = #{item.sortSeq}, duration_time = #{item.durationTime}, duration_unit = #{item.durationUnit}, modifier = #{item.modifier}, update_time = #{item.updateTime}
where id = #{item.inspectionRouteSubId}

mapper.update:
update sys_video_inspection_route_record
set end_time = #{param.endTime}, modifier = #{param.modifier},

    duration = duration + #{param.duration},


    start_time = #{param.startTime},

update_time = #{param.updateTime}
where id = #{param.id}

mapper.select:
select count(*) inspectionRouteCount
from sys_video_inspection_route
where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0

    and create_time >= #{startTime}


    and create_time <= #{endTime}

select IFNULL(sum(duration), 0) inspectionDuration, count(*) inspectionTimes
from sys_video_inspection_route_record
where tenant_id = #{tenantId} and industry_code = #{industryCode} and delete_flag = 0 and duration > 0

    and create_time >= #{startTime}


    and create_time <= #{endTime}

select distinct s.id, s.inspection_route_name, s.`pause_cruise_flag`, s.route_status, s.creator, s.create_time, s.modifier, s.update_time from sys_video_inspection_route s where s.delete_flag = 0
and s.inspection_route_name like CONCAT('%', #{param.inspectionRouteName}, '%')
and s.creator like CONCAT('%', #{param.creator}, '%')
${param.dataScope}
and s.modifier like CONCAT('%',#{param.modifier},'%')
and s.create_time >= #{param.createTimeBegin}
and s.create_time <= #{param.createTimeEnd}
and s.update_time >= #{param.updateTimeBegin}
and s.update_time <= #{param.updateTimeEnd}
order by s.create_time
desc
asc
order by s.update_time
desc
asc
order by s.create_time desc
